import re
from typing import List, Dict, Any, Tuple, Optional

# helper functions are assumed to be available from the platform
# node_by_title(doc, title) -> node dict or None
# node_by_id(doc, node_id) -> node dict or None
# children(doc, node) -> list of child node dicts
# scope_nodes(doc, scope) -> list of child nodes of the scope
# table_rows(node) -> list of (row_index, {col: cell_str})

# ----------------------------------------------------------------------
# Utility helpers
# ----------------------------------------------------------------------
def _get_scope_node(doc, scope_title: str):
    node = node_by_title(doc, scope_title)
    if not node:
        raise ValueError(f"Scope {scope_title!r} not found")
    return node

def _find_child_by_title(node, title_pattern: str):
    """Return first child node whose title contains the given pattern."""
    for child in children(doc, node):
        if title_pattern in child.get("title", ""):
            return child
    return None

def _parse_object_line(line: str) -> Tuple[str, str]:
    """
    Parse lines of the form:
        Object 0: green rubber cube (color=green, material=rubber, shape=cube)
    Returns (id_str, description)
    """
    m = re.match(r"Object\s+(\d+):\s+(.+?)\s*\(", line.strip())
    if not m:
        raise ValueError(f"Cannot parse object line: {line!r}")
    oid = m.group(1)
    desc = m.group(2).strip()
    id_str = f"{oid} {desc}"
    return id_str, desc

def _parse_frame(line: str) -> int:
    m = re.match(r"Frame\s+(\d+):", line.strip())
    if m:
        return int(m.group(1))
    raise ValueError(f"Cannot parse frame from line: {line!r}")

# ----------------------------------------------------------------------
# Main functions
# ----------------------------------------------------------------------
def entities(doc: Dict[str, Any], scope: str) -> List[Dict[str, Any]]:
    """
    Returns list of {"id": str, "description": str} for every distinct entity
    in the scope (objects defined in the <scope>: Objects node).
    """
    scope_node = _get_scope_node(doc, scope)
    obj_node = _find_child_by_title(scope_node, ": Objects")
    if not obj_node:
        return []
    entities = []
    seen = set()
    for line in obj_node.get("lines", []):
        try:
            obj_id, desc = _parse_object_line(line)
        except ValueError:
            continue
        if obj_id not in seen:
            seen.add(obj_id)
            entities.append({"id": obj_id, "description": desc})
    return entities


def recorded_end(doc: Dict[str, Any], scope: str) -> Optional[float]:
    """
    Returns the last time point (frame number) covered by the scope's records,
    or None if no time information is available.
    """
    scope_node = _get_scope_node(doc, scope)
    max_frame = None
    # Check events lines
    events_node = _find_child_by_title(scope_node, ": Events")
    if events_node:
        for line in events_node.get("lines", []):
            try:
                f = _parse_frame(line)
                if max_frame is None or f > max_frame:
                    max_frame = f
            except ValueError:
                pass
    # Check motion log table
    motion_node = _find_child_by_title(scope_node, ": Motion log")
    if motion_node and motion_node.get("kind") == "table":
        for _, row in table_rows(motion_node):
            f_str = row.get("frame", "")
            try:
                f = int(f_str)
                if max_frame is None or f > max_frame:
                    max_frame = f
            except ValueError:
                pass
    return max_frame


def inputs(doc: Dict[str, Any], scope: str) -> List[Dict[str, Any]]:
    """
    Returns a list of input records that enter the process from outside.
    """
    scope_node = _get_scope_node(doc, scope)
    events_node = _find_child_by_title(scope_node, ": Events")
    motion_node = _find_child_by_title(scope_node, ": Motion log")
    inputs = []

    # Build dictionary of first motion row for each object
    first_motion = {}
    if motion_node and motion_node.get("kind") == "table":
        for row_index, row in table_rows(motion_node):
            obj_id = row.get("object", "")
            if obj_id and obj_id not in first_motion:
                first_motion[obj_id] = (row_index, row)

    if events_node:
        for line_index, line in enumerate(events_node.get("lines", [])):
            if "is in view when the video begins." in line:
                # Parse object id
                try:
                    obj_id, desc = _parse_object_line(line.split(":",1)[1].strip())
                except Exception:
                    continue
                # Prepare input
                inp_id = f"in_{obj_id}"
                # Use first motion row if available for fields
                fields = {}
                src = [[events_node["node_id"], line_index]]
                if obj_id in first_motion:
                    row_index, row = first_motion[obj_id]
                    # Convert numeric fields
                    for key in ["x", "y", "vx", "vy", "speed"]:
                        val = row.get(key, "")
                        try:
                            fields[key] = float(val)
                        except ValueError:
                            pass
                    src.append([motion_node["node_id"], row_index,
                                 ["x", "y", "vx", "vy", "speed"]])
                inputs.append({
                    "id": inp_id,
                    "time": 0.0,
                    "kind": "arrival",
                    "entities": [obj_id],
                    "fields": fields,
                    "src": src
                })

    return inputs


def outcomes(doc: Dict[str, Any], scope: str) -> List[Dict[str, Any]]:
    """
    Returns a list of outcome records that result from the process.
    """
    scope_node = _get_scope_node(doc, scope)
    events_node = _find_child_by_title(scope_node, ": Events")
    outcomes = []

    if not events_node:
        return outcomes

    for line_index, line in enumerate(events_node.get("lines", [])):
        if "is in view when the video begins." in line:
            continue  # input, not outcome
        # exit event
        m_exit = re.search(r"Object\s+(\d+)\s+.*? exits(?: the scene| the video|).*", line)
        if m_exit and "exits" in line:
            obj_id_num = m_exit.group(1)
            # Build object id string; need description part. We can search in objects list
            obj_desc = None
            obj_node = _find_child_by_title(scope_node, ": Objects")
            if obj_node:
                for l in obj_node.get("lines", []):
                    if f"Object {obj_id_num}:" in l:
                        try:
                            obj_desc_line = l.split(":",1)[1].strip()
                            mdesc = re.match(r"(.+?)\s*\(", obj_desc_line)
                            desc = mdesc.group(1).strip() if mdesc else "unknown"
                            obj_desc = f"{obj_id_num} {desc}"
                            break
                        except Exception:
                            pass
            if obj_desc is None:
                obj_desc = f"{obj_id_num}"
            outcomes.append({
                "time": _parse_frame(line),
                "kind": "exit",
                "entities": [obj_desc],
                "value": None,
                "src": [[events_node["node_id"], line_index]]
            })
            continue

        # collision event
        if "collides with" in line:
            # pattern: Object X ... collides with Object Y ...
            pattern = r"Object\s+(\d+)\s+.*?collides with Object\s+(\d+)\s+.*?"
            m = re.search(pattern, line)
            if m:
                oid1 = m.group(1)
                oid2 = m.group(2)
                # Get descriptions
                obj1_desc = None
                obj2_desc = None
                obj_node = _find_child_by_title(scope_node, ": Objects")
                if obj_node:
                    for l in obj_node.get("lines", []):
                        if l.startswith(f"Object {oid1}:"):
                            try:
                                d1 = l.split(":",1)[1].strip()
                                d1_desc = re.match(r"(.+?)\s*\(", d1).group(1).strip()
                                obj1_desc = f"{oid1} {d1_desc}"
                            except Exception:
                                pass
                        if l.startswith(f"Object {oid2}:"):
                            try:
                                d2 = l.split(":",1)[1].strip()
                                d2_desc = re.match(r"(.+?)\s*\(", d2).group(1).strip()
                                obj2_desc = f"{oid2} {d2_desc}"
                            except Exception:
                                pass
                if obj1_desc is None:
                    obj1_desc = oid1
                if obj2_desc is None:
                    obj2_desc = oid2
                outcomes.append({
                    "time": _parse_frame(line),
                    "kind": "collision",
                    "entities": [obj1_desc, obj2_desc],
                    "value": None,
                    "src": [[events_node["node_id"], line_index]]
                })
            continue

        # Any other event not parsed is ignored for outcomes

    return outcomes


