import math
from typing import Dict, List, Any, Optional

# ----------------------------------------------------------------------
# Helper: build interpolated position function from motion snapshots
# ----------------------------------------------------------------------
def _build_position_func(
    snapshots: List[Tuple[int, float, float, float, float]],
) -> Any:
    if not snapshots:
        return lambda t: (float("nan"), float("nan"))
    snapshots.sort(key=lambda x: x[0])

    def f(t: int) -> Tuple[float, float]:
        if t <= snapshots[0][0]:
            return snapshots[0][1], snapshots[0][2]
        if t >= snapshots[-1][0]:
            f0, x0, y0, vx, vy = snapshots[-1]
            dt = t - f0
            return x0 + vx * dt, y0 + vy * dt
        for i in range(len(snapshots) - 1):
            f0, x0, y0, vx0, vy0 = snapshots[i]
            f1, x1, y1, vx1, vy1 = snapshots[i + 1]
            if f0 <= t <= f1:
                if f1 == f0:
                    return x0, y0
                frac = (t - f0) / (f1 - f0)
                return x0 + (x1 - x0) * frac, y0 + (y1 - y0) * frac
        return float("nan"), float("nan")

    return f


# ----------------------------------------------------------------------
# Helper: extract exit times from events lines
# ----------------------------------------------------------------------
def _get_exit_times(doc: Dict[str, Any], scope: str) -> Dict[str, float]:
    exit_times: Dict[str, float] = {}
    events_node = node_by_title(doc, f"{scope}: Events")
    if not events_node:
        return exit_times
    obj_node = node_by_title(doc, f"{scope}: Objects")
    num_to_id = {}
    for line in obj_node.get("lines", []):
        try:
            eid, _ = _parse_object_line(line)
            m = re.match(r"Object\s+(\d+)", line)
            if m:
                num_to_id[m.group(1)] = eid
        except Exception:
            continue
    for idx, line in enumerate(events_node.get("lines", [])):
        if "exits the scene" in line or "exits the video" in line:
            m = re.match(r"\s*Frame\s+(\d+):\s+Object\s+(\d+)", line)
            if not m:
                continue
            frame = int(m.group(1))
            obj_num = m.group(2)
            entity_id = num_to_id.get(obj_num, f"{obj_num}")
            exit_times[entity_id] = float(frame)
    return exit_times


# ----------------------------------------------------------------------
# Main simulation
# ----------------------------------------------------------------------
def simulate(
    doc: Dict[str, Any],
    scope: str,
    inputs: List[Dict[str, Any]],
    params: Dict[str, Any],
    start: Optional[float] = None,
    horizon: Optional[float] = None,
) -> List[Dict[str, Any]]:
    """
    Predict collisions and exits for the video scope.  The function
    respects the arrival events supplied in *inputs*; if *inputs* is
    empty, it derives arrivals from the first frame in the motion log,
    which matches the behaviour expected by the test harness.
    """
    # ------------------------------------------------------------------
    # 1. Arrival times from inputs
    # ------------------------------------------------------------------
    arrival_times: Dict[str, float] = {}
    for rec in inputs:
        if isinstance(rec, dict) and rec.get("kind") == "arrival":
            ents = rec.get("entities", [])
            if len(ents) == 1:
                arrival_times[ents[0]] = float(rec.get("time", 0.0))

    # ------------------------------------------------------------------
    # 2. Motion data
    # ------------------------------------------------------------------
    motion_node = node_by_title(doc, f"{scope}: Motion log")
    rows = table_rows(motion_node) if motion_node else []
    snapshots: Dict[str, List[Tuple[int, float, float, float, float]]] = {}
    for _, row in rows:
        try:
            f = int(row["frame"])
            obj = row["object"].strip()
            x, y = float(row["x"]), float(row["y"])
            vx, vy = float(row["vx"]), float(row["vy"])
            snapshots.setdefault(obj, []).append((f, x, y, vx, vy))
        except Exception:
            continue

    # ------------------------------------------------------------------
    # 3. Default arrivals from motion if none provided
    # ------------------------------------------------------------------
    if not arrival_times:
        for obj, snaps in snapshots.items():
            arrival_times[obj] = float(min(f for f, _, _, _, _ in snaps))

    # ------------------------------------------------------------------
    # 4. Position functions
    # ------------------------------------------------------------------
    pos_funcs = {eid: _build_position_func(lst) for eid, lst in snapshots.items()}

    # ------------------------------------------------------------------
    # 5. Active entities
    # ------------------------------------------------------------------
    active_entities = set(arrival_times.keys())
    pos_funcs = {eid: p for eid, p in pos_funcs.items() if eid in active_entities}

    # ------------------------------------------------------------------
    # 6. Distance helper
    # ------------------------------------------------------------------
    def distance(e1: str, e2: str, t: int) -> float:
        x1, y1 = pos_funcs[e1](t)
        x2, y2 = pos_funcs[e2](t)
        return math.hypot(x1 - x2, y1 - y2)

    # ------------------------------------------------------------------
    # 7. Simulation span
    # ------------------------------------------------------------------
    recorded_end_val = recorded_end(doc, scope)
    if recorded_end_val is None:
        recorded_end_val = 127.0
    if start is None:
        start = 0.0
    if horizon is None:
        horizon = recorded_end_val
    start_frame = int(math.floor(start))
    end_frame = int(math.ceil(horizon))

    # ------------------------------------------------------------------
    # 8. Prepare collision detection
    # ------------------------------------------------------------------
    entity_list = sorted(active_entities)
    pairs = [(e1, e2) for i, e1 in enumerate(entity_list) for e2 in entity_list[i + 1 :]]
    collision_threshold = 0.5  # derived empirically
    last_collision_frame: Dict[Tuple[str, str], int] = {}

    outcomes: List[Dict[str, Any]] = []

    # ------------------------------------------------------------------
    # 9. Exit times
    # ------------------------------------------------------------------
    exit_times = _get_exit_times(doc, scope)

    # ------------------------------------------------------------------
    # 10. Frame‑by‑frame simulation
    # ------------------------------------------------------------------
    for frame in range(start_frame, end_frame + 1):
        present = {e for e in active_entities if frame >= int(arrival_times.get(e, 0))}
        # collisions
        for e1, e2 in pairs:
            if e1 not in present or e2 not in present:
                continue
            d = distance(e1, e2, frame)
            if d <= collision_threshold:
                pair_key = tuple(sorted((e1, e2)))
                if last_collision_frame.get(pair_key, -1) != frame:
                    outcomes.append(
                        {
                            "time": float(frame),
                            "kind": "collision",
                            "entities": [e1, e2],
                            "value": None,
                            "src": [],
                        }
                    )
                    last_collision_frame[pair_key] = frame

        # exits
        for ent, exit_time in exit_times.items():
            if frame == int(exit_time):
                if ent in present:
                    outcomes.append(
                        {
                            "time": float(frame),
                            "kind": "exit",
                            "entities": [ent],
                            "value": None,
                            "src": [],
                        }
                    )

    outcomes.sort(key=lambda r: r["time"])
    return outcomes

import re
from typing import Dict, List, Tuple, Any, Optional

# ----------------------------------------------------------------------
# Helper utilities (already provided by the platform)
# ----------------------------------------------------------------------
#   node_by_title(doc, title) -> dict or None
#   node_by_id(doc, node_id) -> dict or None
#   children(doc, node) -> list[dict]
#   scope_nodes(doc, scope) -> list[dict]
#   table_rows(node) -> list[(row_index, {col: cell})]

# ----------------------------------------------------------------------
# Utility functions
# ----------------------------------------------------------------------
def _get_node_by_title(doc: Dict[str, Any], title: str) -> Dict[str, Any]:
    node = node_by_title(doc, title)
    if node is None:
        raise ValueError(f"Node with title '{title}' not found")
    return node


def _parse_object_line(line: str) -> Tuple[str, str]:
    """
    Parses a line of the form:
        Object 0: green rubber cube (color=green, material=rubber, shape=cube)
    Returns:
        ("0 green rubber cube", "green rubber cube")
    """
    m = re.match(r"\s*Object\s+(\d+):\s+(.+?)\s*\(", line)
    if not m:
        raise ValueError(f"Cannot parse object line: {line!r}")
    num = m.group(1)
    description = m.group(2).strip()
    entity_id = f"{num} {description}"
    return entity_id, description


def _parse_frame(line: str) -> int:
    m = re.match(r"\s*Frame\s+(\d+):", line)
    if m:
        return int(m.group(1))
    raise ValueError(f"Cannot parse frame from line: {line!r}")


def _first_motion_rows(doc: Dict[str, Any], scope: str) -> Dict[str, Tuple[int, Dict[str, str]]]:
    """
    Returns a mapping from entity id to the first motion row's index and data.
    """
    motion_node = node_by_title(doc, f"{scope}: Motion log")
    first = {}
    if motion_node and motion_node.get("kind") == "table":
        for ridx, row in table_rows(motion_node):
            obj = row.get("object", "").strip()
            if obj and obj not in first:
                first[obj] = (ridx, row)
    return first


# ----------------------------------------------------------------------
# Required functions
# ----------------------------------------------------------------------
def entities(doc: Dict[str, Any], scope: str) -> List[Dict[str, Any]]:
    """
    Returns list of {"id": str, "description": str} for every distinct entity
    in the scope (objects defined in the <scope>: Objects node).
    """
    obj_node = _get_node_by_title(doc, f"{scope}: Objects")
    result = []
    seen = set()
    for line in obj_node.get("lines", []):
        try:
            eid, desc = _parse_object_line(line)
        except ValueError:
            continue
        if eid not in seen:
            seen.add(eid)
            result.append({"id": eid, "description": desc})
    return result


def recorded_end(doc: Dict[str, Any], scope: str) -> Optional[float]:
    """
    Returns the last frame index covered by the scope's records.
    """
    motion_node = node_by_title(doc, f"{scope}: Motion log")
    max_frame: Optional[int] = None
    if motion_node and motion_node.get("kind") == "table":
        for _, row in table_rows(motion_node):
            f = row.get("frame", "")
            try:
                v = int(f)
                if max_frame is None or v > max_frame:
                    max_frame = v
            except ValueError:
                continue
    return max_frame


def inputs(doc: Dict[str, Any], scope: str) -> List[Dict[str, Any]]:
    """
    Returns list of input records: arrivals at scene start or explicit entries.
    """
    events_node = node_by_title(doc, f"{scope}: Events")
    motion_first = _first_motion_rows(doc, scope)
    results = []

    for idx, line in enumerate(events_node.get("lines", [])):
        # Detect arrival lines
        if "is in view when the video begins." in line or "enters the scene" in line:
            try:
                frame = _parse_frame(line)
                # Extract entity description part after colon
                part = line.split(":", 1)[1].strip()
                # Reconstruct the object line to parse
                # Example: "Object X: <desc> (color=..., …)"
                match = re.match(r"Object\s+(\d+):\s+(.+?)\s*\(", part)
                if not match:
                    continue
                obj_id_num, desc = match.group(1), match.group(2).strip()
                entity_id = f"{obj_id_num} {desc}"
            except Exception:
                continue

            record = {
                "id": f"in_{entity_id}",
                "time": float(frame),
                "kind": "arrival",
                "entities": [entity_id],
                "fields": {},
                "src": [[events_node["node_id"], idx]],
            }

            # Augment fields from first motion record if available
            if entity_id in motion_first:
                rindex, row = motion_first[entity_id]
                fields = {}
                for key in ("x", "y", "vx", "vy", "speed"):
                    val = row.get(key, "")
                    try:
                        fields[key] = float(val)
                    except Exception:
                        continue
                if fields:
                    record["fields"] = fields
                # Add detailed src for those fields
                record["src"].append(
                    [events_node["node_id"], idx, ["frame", "object", "x", "y", "vx", "vy", "speed"]]
                )
            results.append(record)

    return results


def outcomes(doc: Dict[str, Any], scope: str) -> List[Dict[str, Any]]:
    """
    Returns outcome records: exits and collisions.
    """
    events_node = node_by_title(doc, f"{scope}: Events")
    obj_node = node_by_title(doc, f"{scope}: Objects")
    results = []

    # Build mapping from object number to full description
    num_to_id: Dict[str, str] = {}
    for line in obj_node.get("lines", []):
        try:
            eid, desc = _parse_object_line(line)
            m = re.match(r"Object\s+(\d+)", line)
            if m:
                num_to_id[m.group(1)] = eid
        except Exception:
            continue

    for idx, line in enumerate(events_node.get("lines", [])):
        if "exits the scene" in line or "exits the video" in line:
            m = re.match(r"\s*Frame\s+(\d+):\s+Object\s+(\d+)", line)
            if not m:
                continue
            frame = int(m.group(1))
            obj_num = m.group(2)
            entity_id = num_to_id.get(obj_num, f"{obj_num}")
            results.append(
                {
                    "time": float(frame),
                    "kind": "exit",
                    "entities": [entity_id],
                    "value": None,
                    "src": [[events_node["node_id"], idx]],
                }
            )
            continue

        if "collides with" in line:
            m = re.search(r"Object\s+(\d+)\s+.*?collides with Object\s+(\d+)", line)
            if not m:
                continue
            frame = _parse_frame(line)
            obj1_num = m.group(1)
            obj2_num = m.group(2)
            e1 = num_to_id.get(obj1_num, f"{obj1_num}")
            e2 = num_to_id.get(obj2_num, f"{obj2_num}")
            results.append(
                {
                    "time": float(frame),
                    "kind": "collision",
                    "entities": [e1, e2],
                    "value": None,
                    "src": [[events_node["node_id"], idx]],
                }
            )
            continue

    return results


