def _locate_event_line(events_node, frame: int, entities: List[str]) -> Optional[List[Any]]:
    for idx, line in enumerate(events_node.get("lines", [])):
        if f"Frame {frame}:" not in line:
            continue
        # Check that all entity identifiers appear in the line
        if all(e in line for e in entities):
            return [events_node["node_id"], idx]
    return None


